namespace ghidra.app.plugin.core.decompile.actions;

using docking.action;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using ghidra.program.model.scalar;
using ghidra.util;

/**
 * Convert a selected constant in the decompiler to a hexadecimal representation.
 */
public class ConvertHexAction : ConvertConstantAction {

	public ConvertHexAction(DecompilePlugin plugin) : base(plugin, "Convert To Hexadecimal", EquateSymbol.FORMAT_HEX)
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionConvert"));
		setPopupMenuData(new MenuData(new string[] { "Hexadecimal" }, "Decompile"));
	}

	/* @Override */
	public string getMenuPrefix() {
		return "Hexadecimal: ";
	}

	/* @Override */
	public string getMenuDisplay(Scalar scalar, Program program) {
		if (scalar.isSigned()) {
			long v = scalar.getSignedValue();
			string valueStr = Long.toString(v, 16);
			if (v < 0) {
				// use of substring removes '-' prefix for negative value
				return "-0x" + valueStr.substring(1);
			}
			return "0x" + valueStr;
		}
		string valueStr = Long.toHexString(scalar.getUnsignedValue());
		return "0x" + valueStr;
	}

	/* @Override */
	public string getEquateName(Scalar scalar, Program program) {
		if (scalar.isSigned()) {
			long v = scalar.getSignedValue();
			string valueStr = Long.toString(v, 16).toUpperCase();
			if (v < 0) {
				// use of substring removes '-' prefix for negative value
				return "-0x" + valueStr.substring(1);
			}
			return "0x" + valueStr;
		}
		string valueStr = Long.toHexString(scalar.getUnsignedValue()).toUpperCase();
		// Instructions rely on equate which uses 0x prefix (consistent with default scalar formatting)
		return "0x" + valueStr;
	}
}
